/* Tangerine Theme - Auto-generated from tweakcn */

/* Light mode */
[data-theme="tangerine-light"] {
  --background: hsl(330 0% 92.15%);
  --foreground: hsl(0 0% 19.89%);
  --card: hsl(300 50% 100%);
  --card-foreground: hsl(0 0% 19.89%);
  --popover: hsl(300 50% 100%);
  --popover-foreground: hsl(0 0% 19.89%);
  --primary: hsl(13.18 72.31% 55.05%);
  --primary-foreground: hsl(300 50% 100%);
  --secondary: hsl(300 0% 96.06%);
  --secondary-foreground: hsl(214.99 15.5% 34.68%);
  --muted: hsl(300 0% 97.37%);
  --muted-foreground: hsl(219.97 7.71% 45.75%);
  --accent: hsl(207.71 40.61% 88.73%);
  --accent-foreground: hsl(224.53 64.95% 33.15%);
  --destructive: hsl(359.91 86.11% 60.55%);
  --destructive-foreground: hsl(300 50% 100%);
  --border: hsl(209.97 17.74% 87.33%);
  --input: hsl(300 0% 96.06%);
  --ring: hsl(13.18 72.31% 55.05%);
  --chart-1: hsl(210.01 37.79% 66.02%);
  --chart-2: hsl(12.91 72.83% 75.4%);
  --chart-3: hsl(213.13 31.85% 50.54%);
  --chart-4: hsl(216.91 33.93% 42.4%);
  --chart-5: hsl(221.14 46.06% 35.24%);
  --radius: 0.75rem;
  --sidebar: hsl(300 0% 86.98%);
  --sidebar-foreground: hsl(0 0% 19.89%);
  --sidebar-primary: hsl(13.18 72.31% 55.05%);
  --sidebar-primary-foreground: hsl(300 50% 100%);
  --sidebar-accent: hsl(207.71 40.61% 88.73%);
  --sidebar-accent-foreground: hsl(224.53 64.95% 33.15%);
  --sidebar-border: hsl(220.01 24.1% 91.61%);
  --sidebar-ring: hsl(13.18 72.31% 55.05%);
  --font-sans: Inter, sans-serif;
  --font-serif: Source Serif 4, serif;
  --font-mono: JetBrains Mono, monospace;
  --shadow-color: hsl(0 0% 0%);
  --shadow-opacity: 0.1;
  --shadow-blur: 3px;
  --shadow-spread: 0px;
  --shadow-offset-x: 0px;
  --shadow-offset-y: 1px;
  --letter-spacing: 0em;
  --spacing: 0.25rem;
  --shadow-2xs: 0px 1px 3px 0px hsl(0 0% 0% / 0.05);
  --shadow-xs: 0px 1px 3px 0px hsl(0 0% 0% / 0.05);
  --shadow-sm:
    0px 1px 3px 0px hsl(0 0% 0% / 0.1), 0px 1px 2px -1px hsl(0 0% 0% / 0.1);
  --shadow:
    0px 1px 3px 0px hsl(0 0% 0% / 0.1), 0px 1px 2px -1px hsl(0 0% 0% / 0.1);
  --shadow-md:
    0px 1px 3px 0px hsl(0 0% 0% / 0.1), 0px 2px 4px -1px hsl(0 0% 0% / 0.1);
  --shadow-lg:
    0px 1px 3px 0px hsl(0 0% 0% / 0.1), 0px 4px 6px -1px hsl(0 0% 0% / 0.1);
  --shadow-xl:
    0px 1px 3px 0px hsl(0 0% 0% / 0.1), 0px 8px 10px -1px hsl(0 0% 0% / 0.1);
  --shadow-2xl: 0px 1px 3px 0px hsl(0 0% 0% / 0.25);
  --tracking-normal: 0em;
}

